const MAX_PROMPT_LENGTH = 2000;
const body = $json.body || $json || {};
let { prompt, user_id, source } = body;

if (!prompt || !prompt.toString().trim()) {
  throw new Error('Missing or empty "prompt" field.');
}

let cleanPrompt = prompt.toString().trim();
cleanPrompt = cleanPrompt
  .replace(/<script[\s\S]*?>[\s\S]*?<\/script>/gi, '')
  .replace(/<[^>]+>/g, '');

if (cleanPrompt.length > MAX_PROMPT_LENGTH) {
  cleanPrompt = cleanPrompt.slice(0, MAX_PROMPT_LENGTH);
}

const cleanUserId = (user_id && user_id.toString().trim()) || 'anonymous';
const cleanSource = (source && source.toString().trim().toLowerCase()) || 'web';

return [{
  json: {
    prompt: cleanPrompt,
    user_id: cleanUserId,
    source: cleanSource,
    received_at: new Date().toISOString()
  }
}];

const data = this.getWorkflowStaticData('global');
const userId = $json.user_id;
const now = Date.now();

if (!data.rateHistory) data.rateHistory = {};
if (!data.rateHistory[userId]) data.rateHistory[userId] = [];

data.rateHistory[userId] = data.rateHistory[userId].filter(ts => now - ts < 60 * 60 * 1000);

const last10s = data.rateHistory[userId].filter(ts => now - ts < 10 * 1000).length;
const lastHour = data.rateHistory[userId].length;

let rate_limited = false;
let rate_reason = null;

if (last10s >= 3) {
  rate_limited = true;
  rate_reason = 'Too many requests in a short window. Slow down.';
} else if (lastHour >= 60) {
  rate_limited = true;
  rate_reason = 'Hourly request limit reached.';
} else {
  data.rateHistory[userId].push(now);
}

return [{ json: { ...$json, rate_limited, rate_reason } }];

const blockedWords = ['badword1', 'badword2', 'badword3'];
let text = ($json.prompt || '').toString();
let flagged = false;

for (const word of blockedWords) {
  const re = new RegExp(word, 'gi');
  if (re.test(text)) {
    flagged = true;
    text = text.replace(re, '***');
  }
}

return [{
  json: {
    ...$json,
    prompt: text,
    moderation_flagged: flagged,
    moderation_reason: flagged ? 'Contains blocked terms.' : null
  }
}];

const raw = ($json.source || $json.channel || $json.origin || '').toString().toLowerCase();
let source = 'unknown';

if (raw.includes('tg') || raw.includes('telegram')) source = 'telegram';
else if (raw.includes('phone') || raw.includes('twilio')) source = 'phone';
else if (raw.includes('email') || raw.includes('gmail')) source = 'email';
else if (raw.includes('web') || raw.includes('site')) source = 'web';
else if (raw.includes('cron') || raw.includes('system')) source = 'system';

return [{ json: { ...$json, source } }];
